1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
26	
27	const basePremiumOf = (item: Item): number => 100;
28	
29	export const runScenario = (scenario: Scenario): StepResult[] =>
30	  scenario.steps.map((step) => {
31	    const policyBasePremium = (step as { items: Item[] }).items.reduce(
32	      (sum, item) => sum + basePremiumOf(item),
33	      0,
34	    );
35	    const surcharge =
36	      (policyBasePremium * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;
37	
38	    return {
39	      premium: Math.ceil(policyBasePremium + surcharge + PROCESSING_FEE),
40	    };
41	  });
42

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office — quote: base premiums", () => {
5	  it("empty item list → premium 5 G (only the processing fee)", () => {
6	    const results = runScenario({
7	      customer: { yearsWithMHPCO: 0 },
8	      steps: [{ op: "quote", items: [] }],
9	    });
10	
11	    expect(results).toEqual([{ premium: 5 }]);
12	  });
13	  it("a sword → base premium 100 G", () => {
14	    const results = runScenario({
15	      customer: { yearsWithMHPCO: 0 },
16	      steps: [{ op: "quote", items: [{ type: "sword" }] }],
17	    });
18	
19	    // 100 G base + 10 G first insurance + 5 G fee
20	    expect(results).toEqual([{ premium: 115 }]);
21	  });
22	  it.todo("an amulet → base premium 60 G");
23	  it.todo("a staff → base premium 80 G");
24	  it.todo("a potion → base premium 40 G");
25	  it.todo("a single rune (component) → base premium 25 G");
26	  it.todo("a single moonstone (component) → base premium 25 G");
27	});
28	
29	describe("MHPCO Claim Office — quote: component blocks of 3 alike", () => {
30	  it.todo("2 runes → 50 G base premium (no block)");
31	  it.todo("3 runes → 60 G base premium (block applies)");
32	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
33	  it.todo("7 runes → 175 G base premium");
34	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
35	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
36	});
37	
38	describe("MHPCO Claim Office — quote: premium modifiers", () => {
39	  it.todo("a cursed sword adds a 50 % risk surcharge on the item's base premium");
40	  it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge");
41	  it.todo("a sword with enchantment 4 → no high-enchantment surcharge");
42	  it.todo("a cursed sword with enchantment 5 → both surcharges apply");
43	  it.todo("a customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
44	  it.todo("a customer with 1 year with MHPCO → no loyalty discount");
45	  it.todo("every quote carries a 10 % first insurance surcharge on the policy base premium");
46	  it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
47	  it.todo("a 5 G processing fee is added at the very end of every premium");
48	});
49	
50	describe("MHPCO Claim Office — quote: modifier scope on multi-item policies", () => {
51	  it.todo("cursed sword + plain amulet → item surcharge is 50 G (50 % of the cursed item only), 210 G before policy modifiers and fee");
52	  it.todo("policy-wide modifiers apply to the sum of all item base premiums");
53	});
54	
55	describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
56	  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
57	  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
58	});
59	
60	describe("MHPCO Claim Office — quote: integration examples", () => {
61	  it.todo("newcomer (0 years) with a cursed steel sword, enchantment 3 → premium 165 G");
62	  it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
63	});
64	
65	describe("MHPCO Claim Office — claim: standard reimbursement", () => {
66	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
67	  it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
68	  it.todo("a claim reports the remaining cap after the payout");
69	});
70	
71	describe("MHPCO Claim Office — claim: special clauses", () => {
72	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
73	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
74	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
75	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
76	});
77	
78	describe("MHPCO Claim Office — claim: deductible per damage event", () => {
79	  it.todo("dragon attack damaging an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)");
80	});
81	
82	describe("MHPCO Claim Office — claim: rounding in the MHPCO's favor", () => {
83	  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
84	});
85	
86	describe("MHPCO Claim Office — claim: insurance sum and cap", () => {
87	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
88	  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
89	  it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G");
90	  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remaining cap 600 G");
91	  it.todo("sword insured (cap 2000 G), second claim of 1500 G → payout 600 G, remaining cap 0 G");
92	});
93	
94	describe("MHPCO Claim Office — multiple items of the same type", () => {
95	  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
96	  it.todo("a dragon attack damaging both swords → each damage entry gets its own deductible");
97	  it.todo("more damage entries of a type than the policy covers → error (whole claim rejected)");
98	});
99	
100	describe("MHPCO Claim Office — error cases", () => {
101	  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
102	  it.todo("claim references a damage entry whose item is not part of the policy → error");
103	  it.todo("claim references a damage entry with an unknown item type → error");
104	  it.todo("claim contains a damage entry with amount -200 → error");
105	});
106	
107	describe("MHPCO Claim Office — CLI", () => {
108	  it.todo("reads a JSON scenario from stdin and writes {results: [...]} to stdout");
109	  it.todo("results array has the same length and order as the input steps");
110	  it.todo("on an invalid scenario → exits with a non-zero status code, writes an error description to stderr and no results to stdout");
111	});
